/*!
 * Themeasy — Code Terminal
 *
 * Typing engine for the .tms-code-terminal widget: command lines type in
 * character-by-character behind a block cursor, output/success/error/comment
 * lines reveal whole with a fast stagger, optionally looping. The markup
 * ships the FULL transcript; the engine snapshots it, arms the root
 * (--armed hides not-yet-shown lines) and replays it — so no-JS renders the
 * complete terminal, the editor preview (--static) never initializes, and
 * prefers-reduced-motion leaves the transcript untouched. IntersectionObserver
 * starts the sequence on view and pauses/resumes it off-screen/on re-entry
 * (battery-friendly). The title-bar copy button copies all command lines via
 * the async Clipboard API and is hidden when the API is unavailable
 * (mirrors social-share-row's guard); success flips the icon to a check and
 * announces "Copied" through a polite live region. One AbortController per
 * instance; reset() restores the full transcript for idempotent re-init.
 *
 * Namespace:    window.Themeasy.codeTerminal
 * Pattern:      IIFE + onDomReady() + boot()
 *
 * @author Themeasy
 * @link https://themeasy.co
 * @since 1.0.0
 */

(function (window, document) {
  'use strict'

  // ------------------------------------------------------------------------
  // Namespace
  // ------------------------------------------------------------------------
  window.Themeasy = window.Themeasy || {}
  window.Themeasy.codeTerminal = window.Themeasy.codeTerminal || {}

  // ------------------------------------------------------------------------
  // Constants
  // ------------------------------------------------------------------------
  const SELECTOR_WIDGET = '.tms-code-terminal'
  const SELECTOR_BODY = '.tms-code-terminal__body'
  const SELECTOR_LINES = '.tms-code-terminal__lines'
  const SELECTOR_LINE = '.tms-code-terminal__line'
  const SELECTOR_TEXT = '.tms-code-terminal__text'
  const SELECTOR_COPY = '.tms-code-terminal__copy'
  const SELECTOR_COPY_STATUS = '.tms-code-terminal__copy-status'

  const CLASS_STATIC = 'tms-code-terminal--static'
  const CLASS_ARMED = 'tms-code-terminal--armed'
  const CLASS_LINE_SHOWN = 'tms-code-terminal__line--shown'
  const CLASS_LINE_COMMAND = 'tms-code-terminal__line--command'
  const CLASS_CURSOR = 'tms-code-terminal__cursor'
  const CLASS_CURSOR_TYPING = 'tms-code-terminal__cursor--typing'
  const CLASS_COPY_COPIED = 'tms-code-terminal__copy--copied'

  const INIT_FLAG = 'tmsCodeTerminalInit'
  const DATA_KEY = '_tmsCodeTerminal'

  const STAGGER_MS = 160
  const LOOP_HOLD_MS = 2500
  const COPY_REVERT_MS = 1600
  const IO_THRESHOLD = 0.35

  // ------------------------------------------------------------------------
  // Utils
  // ------------------------------------------------------------------------
  function onDomReady(fn) {
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', fn, { once: true })
      return
    }
    fn()
  }

  function prefersReducedMotion() {
    return typeof window.matchMedia === 'function' &&
      window.matchMedia('(prefers-reduced-motion: reduce)').matches
  }

  function getNumberAttr(el, name, fallback) {
    const raw = el.getAttribute(name)
    if (raw === null || raw === '') return fallback
    const n = parseFloat(raw)
    return Number.isFinite(n) ? n : fallback
  }

  function getBoolAttr(el, name, fallback) {
    const raw = el.getAttribute(name)
    if (raw === null) return fallback
    return raw === 'true' || raw === '1' || raw === 'yes'
  }

  function clamp(n, min, max) {
    return Math.min(Math.max(n, min), max)
  }

  // ------------------------------------------------------------------------
  // Scheduler — one pending continuation per instance. The engine is strictly
  // sequential, so a single timer slot supports pause (IO exit) and resume
  // (IO re-entry) with the remaining time preserved.
  // ------------------------------------------------------------------------
  function wait(inst, ms, fn) {
    if (inst.destroyed) return

    inst.pendingFn = fn
    inst.pendingRemaining = ms

    if (inst.paused) return

    inst.pendingStamp = Date.now()
    inst.timer = window.setTimeout(function () {
      inst.timer = null
      inst.pendingFn = null
      fn()
    }, ms)
  }

  function pauseEngine(inst) {
    if (inst.paused || inst.destroyed) return
    inst.paused = true

    if (inst.timer) {
      window.clearTimeout(inst.timer)
      inst.timer = null
      inst.pendingRemaining = Math.max(0, inst.pendingRemaining - (Date.now() - inst.pendingStamp))
    }
  }

  function resumeEngine(inst) {
    if (!inst.paused || inst.destroyed) return
    inst.paused = false

    if (inst.pendingFn) {
      wait(inst, inst.pendingRemaining, inst.pendingFn)
    }
  }

  // ------------------------------------------------------------------------
  // Copy button — async Clipboard API only; hidden when unavailable.
  // ------------------------------------------------------------------------
  function getCommandsText(inst) {
    const parts = []

    inst.lines.forEach(function (li, index) {
      if (!li.classList.contains(CLASS_LINE_COMMAND)) return

      // Snapshots hold the full text mid-typing; without them (reduced
      // motion — never armed) the DOM already carries the full transcript.
      let value = inst.snapshots.length ? inst.snapshots[index] : null

      if (value == null) {
        const textEl = li.querySelector(SELECTOR_TEXT)
        value = textEl ? textEl.textContent : ''
      }

      value = String(value).trim()
      if (value) parts.push(value)
    })

    return parts.join('\n')
  }

  function applyCopiedState(inst, button) {
    const status = inst.root.querySelector(SELECTOR_COPY_STATUS)
    const label = button.getAttribute('data-copied-label') || 'Copied'

    button.classList.add(CLASS_COPY_COPIED)
    if (status) status.textContent = label

    if (inst.copyTimer) window.clearTimeout(inst.copyTimer)

    inst.copyTimer = window.setTimeout(function () {
      inst.copyTimer = null
      button.classList.remove(CLASS_COPY_COPIED)
      if (status) status.textContent = ''
    }, COPY_REVERT_MS)
  }

  function setupCopy(inst) {
    const button = inst.root.querySelector(SELECTOR_COPY)
    if (!button) return

    const supported = !!(window.navigator && window.navigator.clipboard &&
      typeof window.navigator.clipboard.writeText === 'function' && window.isSecureContext)

    if (!supported) {
      button.hidden = true
      return
    }

    button.addEventListener('click', function () {
      const text = getCommandsText(inst)
      if (!text) return

      window.navigator.clipboard.writeText(text).then(
        function () {
          applyCopiedState(inst, button)
        },
        function () {
          // Clipboard rejected (permissions) — leave the button untouched.
        }
      )
    }, { signal: inst.controller.signal })
  }

  // ------------------------------------------------------------------------
  // Cursor — a block that lives inline INSIDE the active command's text span
  // (after a dedicated text node), so it wraps with the text and always sits
  // right after the last typed character.
  // ------------------------------------------------------------------------
  function detachCursor(inst) {
    if (inst.cursor && inst.cursor.parentNode) {
      inst.cursor.parentNode.removeChild(inst.cursor)
    }
  }

  function beginCommandLine(inst, li) {
    const textEl = li.querySelector(SELECTOR_TEXT)
    if (!textEl) return null

    textEl.textContent = ''

    const node = document.createTextNode('')
    textEl.appendChild(node)

    if (inst.opts.showCursor) {
      if (!inst.cursor) {
        inst.cursor = document.createElement('span')
        inst.cursor.className = CLASS_CURSOR
      }

      inst.cursor.classList.add(CLASS_CURSOR_TYPING)
      textEl.appendChild(inst.cursor)
    }

    return node
  }

  // ------------------------------------------------------------------------
  // Typing engine
  // ------------------------------------------------------------------------
  function pinScroll(inst) {
    const body = inst.body

    // Keep the newest line in view whenever min-height (or any outer cap)
    // makes the body overflow; a no-op otherwise.
    if (body.scrollHeight > body.clientHeight) {
      body.scrollTop = body.scrollHeight
    }
  }

  function charDelay(inst, prevChar) {
    const base = inst.opts.typingSpeed
    if (!inst.opts.naturalRhythm) return base

    // Subtle human jitter: +/- around the base speed, with a small extra
    // beat after each word (space) — never mechanical, never sluggish.
    let ms = base * (0.6 + Math.random() * 0.85)
    if (prevChar === ' ') ms += base * 0.9

    return clamp(ms, 8, 600)
  }

  function typeCommand(inst, index, done) {
    const li = inst.lines[index]
    const target = inst.snapshots[index] || ''
    const node = beginCommandLine(inst, li)

    if (!node) {
      done()
      return
    }

    let pos = 0

    function step() {
      if (inst.destroyed) return

      node.nodeValue = target.slice(0, pos)
      pinScroll(inst)

      if (pos >= target.length) {
        // Typed out — let the cursor idle-blink at the end of the command.
        if (inst.cursor) inst.cursor.classList.remove(CLASS_CURSOR_TYPING)
        done()
        return
      }

      const prevChar = pos > 0 ? target.charAt(pos - 1) : ''
      pos += 1

      wait(inst, charDelay(inst, prevChar), step)
    }

    step()
  }

  function pauseAfter(inst, index) {
    if (index >= inst.lines.length - 1) return 0

    const currentIsCommand = inst.lines[index].classList.contains(CLASS_LINE_COMMAND)
    const nextIsCommand = inst.lines[index + 1].classList.contains(CLASS_LINE_COMMAND)

    // Fast stagger only between consecutive output-ish lines; a command on
    // either side gets the full human beat (execute / pick up typing again).
    if (!currentIsCommand && !nextIsCommand) return STAGGER_MS

    return inst.opts.linePauseMs
  }

  function runLine(inst, index) {
    if (inst.destroyed) return

    if (index >= inst.lines.length) {
      finishSequence(inst)
      return
    }

    const li = inst.lines[index]
    const extraDelayMs = clamp(getNumberAttr(li, 'data-delay', 0), 0, 30) * 1000

    wait(inst, extraDelayMs, function () {
      li.classList.add(CLASS_LINE_SHOWN)
      pinScroll(inst)

      if (li.classList.contains(CLASS_LINE_COMMAND)) {
        typeCommand(inst, index, function () {
          wait(inst, pauseAfter(inst, index), function () {
            runLine(inst, index + 1)
          })
        })
        return
      }

      wait(inst, pauseAfter(inst, index), function () {
        runLine(inst, index + 1)
      })
    })
  }

  function resetPass(inst) {
    detachCursor(inst)

    inst.lines.forEach(function (li, index) {
      li.classList.remove(CLASS_LINE_SHOWN)

      if (li.classList.contains(CLASS_LINE_COMMAND)) {
        const textEl = li.querySelector(SELECTOR_TEXT)
        if (textEl) textEl.textContent = inst.snapshots[index] || ''
      }
    })
  }

  function finishSequence(inst) {
    if (inst.destroyed) return

    // Without loop the cursor stays blinking at the last command — a living
    // terminal, not a dead frame.
    if (!inst.opts.loop) return

    wait(inst, LOOP_HOLD_MS, function () {
      resetPass(inst)
      runLine(inst, 0)
    })
  }

  function startSequence(inst) {
    if (inst.destroyed || inst.started) return
    inst.started = true

    wait(inst, inst.opts.startDelayMs, function () {
      runLine(inst, 0)
    })
  }

  // ------------------------------------------------------------------------
  // Viewport gate — starts once on view (threshold ~0.35) and pauses the
  // engine while off-screen, resuming on re-entry.
  // ------------------------------------------------------------------------
  function observeViewport(inst) {
    if (typeof window.IntersectionObserver !== 'function') {
      startSequence(inst)
      return
    }

    inst.io = new window.IntersectionObserver(function (entries) {
      const visible = entries.some(function (entry) {
        return entry.isIntersecting
      })

      if (visible) {
        if (!inst.started) {
          if (inst.opts.startOnView) startSequence(inst)
          return
        }

        resumeEngine(inst)
        return
      }

      // Only the on-view mode parks off-screen. With the option off the author
      // asked for it to run regardless, and observe() always fires once with
      // isIntersecting:false — which would otherwise pause it immediately.
      if (inst.started && inst.opts.startOnView) pauseEngine(inst)
    }, { threshold: IO_THRESHOLD })

    inst.io.observe(inst.root)

    if (!inst.opts.startOnView) {
      startSequence(inst)
    }
  }

  // ------------------------------------------------------------------------
  // Instance lifecycle
  // ------------------------------------------------------------------------
  function readOptions(root) {
    return {
      typingSpeed: clamp(getNumberAttr(root, 'data-typing-speed', 45), 10, 300),
      linePauseMs: clamp(getNumberAttr(root, 'data-line-pause', 0.5), 0, 10) * 1000,
      startDelayMs: clamp(getNumberAttr(root, 'data-start-delay', 0.3), 0, 10) * 1000,
      startOnView: getBoolAttr(root, 'data-start-on-view', true),
      loop: getBoolAttr(root, 'data-loop', false),
      showCursor: getBoolAttr(root, 'data-show-cursor', true),
      naturalRhythm: getBoolAttr(root, 'data-natural-rhythm', true),
    }
  }

  /**
   * Build (or skip) the terminal engine for one widget root.
   *
   * @param {HTMLElement} root The .tms-code-terminal element.
   */
  function buildInstance(root) {
    // Editor preview is static: full transcript, no engine, no clipboard.
    if (root.classList.contains(CLASS_STATIC)) return

    // Prevent duplicate initialization.
    if (root.dataset[INIT_FLAG] === '1') return

    const body = root.querySelector(SELECTOR_BODY)
    const list = root.querySelector(SELECTOR_LINES)
    if (!body || !list) return

    root.dataset[INIT_FLAG] = '1'

    const inst = {
      root: root,
      body: body,
      lines: Array.prototype.slice.call(list.querySelectorAll(SELECTOR_LINE)),
      snapshots: [],
      cursor: null,
      controller: new AbortController(),
      io: null,
      timer: null,
      pendingFn: null,
      pendingRemaining: 0,
      pendingStamp: 0,
      copyTimer: null,
      paused: false,
      started: false,
      destroyed: false,
      opts: readOptions(root),
    }

    root[DATA_KEY] = inst

    setupCopy(inst)

    // Reduced motion (or an empty terminal): the server-rendered transcript
    // IS the experience — never arm, never hide, never blink.
    if (!inst.lines.length || prefersReducedMotion()) return

    // Snapshot the full transcript BEFORE hiding anything, so content is
    // only ever hidden with the engine standing by to retype it.
    inst.lines.forEach(function (li) {
      const textEl = li.querySelector(SELECTOR_TEXT)
      inst.snapshots.push(textEl ? textEl.textContent : '')
    })

    root.classList.add(CLASS_ARMED)

    observeViewport(inst)
  }

  /**
   * Kill timers/observers/listeners and restore the full transcript.
   *
   * @param {HTMLElement} root The .tms-code-terminal element.
   */
  function teardown(root) {
    const inst = root[DATA_KEY]

    if (inst) {
      inst.destroyed = true

      if (inst.timer) window.clearTimeout(inst.timer)
      if (inst.copyTimer) window.clearTimeout(inst.copyTimer)
      if (inst.io) inst.io.disconnect()
      inst.controller.abort()

      detachCursor(inst)

      // Restore the full server transcript on every line.
      inst.lines.forEach(function (li, index) {
        li.classList.remove(CLASS_LINE_SHOWN)

        if (inst.snapshots.length && li.classList.contains(CLASS_LINE_COMMAND)) {
          const textEl = li.querySelector(SELECTOR_TEXT)
          if (textEl) textEl.textContent = inst.snapshots[index] || ''
        }
      })

      delete root[DATA_KEY]
    }

    const button = root.querySelector(SELECTOR_COPY)
    if (button) {
      button.hidden = false
      button.classList.remove(CLASS_COPY_COPIED)
    }

    const status = root.querySelector(SELECTOR_COPY_STATUS)
    if (status) status.textContent = ''

    root.classList.remove(CLASS_ARMED)
    delete root.dataset[INIT_FLAG]
  }

  // ------------------------------------------------------------------------
  // Public API
  // ------------------------------------------------------------------------

  /**
   * Collect the terminals inside a scope, INCLUDING the scope itself when it is
   * one. querySelectorAll only matches descendants, so without this a caller
   * that hands over the widget's own root — the natural reading of "root" —
   * gets a silent no-op.
   *
   * @param {ParentNode} [root] Root node to scan. Defaults to document.
   * @returns {Array<HTMLElement>} Terminal roots, the scope itself first.
   */
  function collectWidgets(root) {
    const scope = root && root.querySelectorAll ? root : document
    const widgets = Array.prototype.slice.call(scope.querySelectorAll(SELECTOR_WIDGET))

    // document and DocumentFragment carry no matches().
    if (typeof scope.matches === 'function' && scope.matches(SELECTOR_WIDGET)) {
      widgets.unshift(scope)
    }

    return widgets
  }

  /**
   * Reset prior state inside a root (idempotent re-init support).
   *
   * @param {ParentNode} [root] Root node to scan. Defaults to document.
   */
  window.Themeasy.codeTerminal.reset = function (root) {
    collectWidgets(root).forEach(teardown)
  }

  /**
   * Initialize every Code Terminal inside the given root (or document).
   *
   * @param {ParentNode} [root] Root node to scan. Defaults to document.
   */
  window.Themeasy.codeTerminal.init = function (root) {
    collectWidgets(root).forEach(buildInstance)
  }

  // ------------------------------------------------------------------------
  // Central boot
  // ------------------------------------------------------------------------
  function boot() {
    if (document.querySelector(SELECTOR_WIDGET)) {
      window.Themeasy.codeTerminal.init()
    }
  }

  window.Themeasy.codeTerminal.boot = boot

  // Auto-initialize on DOM ready.
  onDomReady(boot)
})(window, document)
